#!/usr/bin/env node
// scripts/patch-android-bridge.mjs
//
// src-tauri/gen/ is gitignored and regenerated by `tauri android init`
// (locally via `npm run android:init` and in CI before every Android build),
// so the Android native bridge Kotlin sources live committed under
// src-tauri/android/ and are injected into the generated project by this
// script. It is idempotent — safe to run any number of times.

import { copyFileSync, existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const genDir = join(root, 'src-tauri', 'gen', 'android');

if (!existsSync(genDir)) {
  console.log('[patch-android-bridge] gen/android belum ada — jalankan `npm run android:init` dulu (lewati).');
  process.exit(0);
}

// 1) Copy the native bridge implementation into the generated app package.
const pkgDir = join(genDir, 'app', 'src', 'main', 'java', 'com', 'copastool', 'app');
mkdirSync(pkgDir, { recursive: true });

// Clean legacy AiOverlay.kt if present in gen
const legacyPath = join(pkgDir, 'AiOverlay.kt');
if (existsSync(legacyPath)) {
  try { rmSync(legacyPath); } catch (_) {}
}

copyFileSync(join(root, 'src-tauri', 'android', 'AndroidBridge.kt'), join(pkgDir, 'AndroidBridge.kt'));
console.log('[patch-android-bridge] AndroidBridge.kt tersalin ke gen/android.');

// 2) Hook it into MainActivity: attach the JS bridge to the main webview.
const mainActivityPath = join(pkgDir, 'MainActivity.kt');
if (!existsSync(mainActivityPath)) {
  console.log('[patch-android-bridge] MainActivity.kt tidak ditemukan — skip patch.');
  process.exit(0);
}
let src = readFileSync(mainActivityPath, 'utf8');

// Migrate any legacy AiOverlay references in MainActivity to AndroidBridge
if (src.includes('AiOverlay.')) {
  src = src.replaceAll('AiOverlay.', 'AndroidBridge.');
  writeFileSync(mainActivityPath, src);
  console.log('[patch-android-bridge] MainActivity.kt dimigrasikan dari AiOverlay ke AndroidBridge.');
}

if (src.includes('CSTL-BRIDGE') || src.includes('CSTL-OVERLAY')) {
  console.log('[patch-android-bridge] MainActivity.kt bridge hook sudah ada (idempoten).');
} else {
  // Ensure the WebView import exists.
  if (!/^import android\.webkit\.WebView$/m.test(src)) {
    src = src.replace(/^import android\.os\.Bundle$/m, 'import android.os.Bundle\nimport android.webkit.WebView');
  }
  // Insert the override just before the final closing brace of the class.
  const hook = `
  // CSTL-BRIDGE — attach the Android native bridge to the main webview
  override fun onWebViewCreate(webView: WebView) {
    super.onWebViewCreate(webView)
    AndroidBridge.attach(this, webView)
  }
`;
  const lastBrace = src.lastIndexOf('}');
  if (lastBrace === -1) {
    console.error('[patch-android-bridge] Gagal mem-patch MainActivity.kt — closing brace tidak ditemukan.');
    process.exit(1);
  }
  src = src.slice(0, lastBrace) + hook + src.slice(lastBrace);
  writeFileSync(mainActivityPath, src);
  console.log('[patch-android-bridge] MainActivity.kt ter-patch.');
}

// Android Back should follow the app's existing Escape dismissal order, and
// edge-to-edge system bars need to expose their real top inset to the reader.
if (src.includes('CSTL-ANDROID-BACK-INSETS')) {
  console.log('[patch-android-bridge] Back/inset handling sudah ada (idempoten).');
} else {
  for (const importLine of [
    'import androidx.activity.OnBackPressedCallback',
    'import androidx.core.view.ViewCompat',
    'import androidx.core.view.WindowInsetsCompat',
  ]) {
    if (!src.includes(importLine)) src = src.replace(/^import android\.webkit\.WebView$/m, `import android.webkit.WebView\n${importLine}`);
  }
  if (!src.includes('private var appWebView: WebView?')) {
    src = src.replace(/class MainActivity : TauriActivity\(\) \{/, 'class MainActivity : TauriActivity() {\n  private var appWebView: WebView? = null');
  }
  src = src.replace(/super\.onCreate\(savedInstanceState\)/, `super.onCreate(savedInstanceState)

    // CSTL-ANDROID-BACK-INSETS — route system Back into the shared Escape flow
    onBackPressedDispatcher.addCallback(this, object : OnBackPressedCallback(true) {
      override fun handleOnBackPressed() {
        appWebView?.evaluateJavascript(
          "(document.activeElement||document).dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true,cancelable:true}))",
          null
        )
      }
    })
    ViewCompat.setOnApplyWindowInsetsListener(window.decorView) { _, insets ->
      val topDp = insets.getInsets(WindowInsetsCompat.Type.statusBars()).top / resources.displayMetrics.density
      appWebView?.evaluateJavascript(
        "document.documentElement.style.setProperty('--android-safe-area-top','" + topDp + "px')",
        null
      )
      insets
    }
    ViewCompat.requestApplyInsets(window.decorView)`);
  if (!src.includes('appWebView = webView')) {
    src = src.replace(/super\.onWebViewCreate\(webView\)/, 'super.onWebViewCreate(webView)\n    appWebView = webView\n    ViewCompat.requestApplyInsets(window.decorView)');
  }
  writeFileSync(mainActivityPath, src);
  console.log('[patch-android-bridge] Back/inset handling ter-patch.');
}

// Repair older generated MainActivity files whose escaped Kotlin dollar sign
// left the CSS inset value as the literal string "${topDp}px" in JavaScript.
const repairedInsetsSrc = src.replace(
  /"document\.documentElement\.style\.setProperty\('--android-safe-area-top','\\u0024\{topDp\}px'\)"/g,
  '"document.documentElement.style.setProperty(\'--android-safe-area-top\',\'" + topDp + "px\')"'
);
if (repairedInsetsSrc !== src) {
  src = repairedInsetsSrc;
  writeFileSync(mainActivityPath, src, 'utf8');
  console.log('[patch-android-bridge] Android status-bar inset delivery diperbaiki.');
}

// 3) Lifecycle hook compatibility
if (src.includes('CSTL-OVERLAY-BG') || src.includes('CSTL-BRIDGE-LIFECYCLE')) {
  if (!src.includes('AndroidBridge.onDestroy()')) {
    src = src.replace(
      /AndroidBridge\.onActivityResumed\(\)\s*\}/,
      'AndroidBridge.onActivityResumed()\n  }\n  override fun onDestroy() {\n    super.onDestroy()\n    AndroidBridge.onDestroy()\n  }'
    );
    writeFileSync(mainActivityPath, src);
    console.log('[patch-android-bridge] MainActivity.kt onDestroy hook ditambahkan.');
  } else {
    console.log('[patch-android-bridge] Lifecycle hook sudah lengkap (idempoten).');
  }
} else {
  const bgHook = `
  // CSTL-BRIDGE-LIFECYCLE — activity lifecycle bridge hooks
  override fun onPause() {
    super.onPause()
    AndroidBridge.onActivityPaused()
  }
  override fun onResume() {
    super.onResume()
    AndroidBridge.onActivityResumed()
  }
  override fun onDestroy() {
    super.onDestroy()
    AndroidBridge.onDestroy()
  }
`;
  const lastBrace = src.lastIndexOf('}');
  if (lastBrace === -1) {
    console.error('[patch-android-bridge] Gagal mem-patch lifecycle — closing brace tidak ditemukan.');
    process.exit(1);
  }
  src = src.slice(0, lastBrace) + bgHook + src.slice(lastBrace);
  writeFileSync(mainActivityPath, src);
  console.log('[patch-android-bridge] Lifecycle hook ter-patch.');
}

// 3b) Route the Android Storage Access Framework folder-picker result to the
// WebView bridge.
if (src.includes('CSTL-SAF-FOLDER')) {
  console.log('[patch-android-bridge] SAF folder callback sudah ada (idempoten).');
} else {
  if (!/^import android\.content\.Intent$/m.test(src)) {
    src = src.replace(/^import android\.os\.Bundle$/m, 'import android.os.Bundle\nimport android.content.Intent');
  }
  const safHook = `
  // CSTL-SAF-FOLDER — return Android's selected document tree to the frontend
  override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {
    super.onActivityResult(requestCode, resultCode, data)
    AndroidBridge.onFolderPickerResult(requestCode, resultCode, data)
  }
`;
  const lastBrace = src.lastIndexOf('}');
  if (lastBrace === -1) {
    console.error('[patch-android-bridge] Gagal mem-patch SAF callback — closing brace tidak ditemukan.');
    process.exit(1);
  }
  src = src.slice(0, lastBrace) + safHook + src.slice(lastBrace);
  writeFileSync(mainActivityPath, src);
  console.log('[patch-android-bridge] SAF folder callback ter-patch.');
}

// The line-editor bottom sheet must resize above Android's keyboard so the
// Save/Cancel footer remains reachable while typing.
const manifestPath = join(genDir, 'app', 'src', 'main', 'AndroidManifest.xml');
if (existsSync(manifestPath)) {
  let manifest = readFileSync(manifestPath, 'utf8');
  let manifestChanged = false;
  const activityTag = /<activity\b[^>]*android:name="\.MainActivity"[^>]*>/s;
  const match = manifest.match(activityTag);
  if (match && !match[0].includes('android:windowSoftInputMode=')) {
    manifest = manifest.replace(activityTag, match[0].replace(/>$/, ' android:windowSoftInputMode="adjustResize">'));
    manifestChanged = true;
    console.log('[patch-android-bridge] MainActivity soft-input resize ter-patch.');
  }
  if (!manifest.includes('android.permission.SYSTEM_ALERT_WINDOW')) {
    manifest = manifest.replace(
      '<uses-permission android:name="android.permission.INTERNET" />',
      '<uses-permission android:name="android.permission.INTERNET" />\n    <uses-permission android:name="android.permission.SYSTEM_ALERT_WINDOW" />\n    <uses-permission android:name="android.permission.VIBRATE" />'
    );
    manifestChanged = true;
    console.log('[patch-android-bridge] SYSTEM_ALERT_WINDOW dan VIBRATE permissions ditambahkan ke manifest.');
  }
  if (manifestChanged) {
    writeFileSync(manifestPath, manifest);
  }
}

// 4) Ensure ic_launcher_background color matches the icon theme (#241e47) instead of white (#fff)
const bgXmlPath = join(genDir, 'app', 'src', 'main', 'res', 'values', 'ic_launcher_background.xml');
if (existsSync(bgXmlPath)) {
  writeFileSync(bgXmlPath, '<?xml version="1.0" encoding="utf-8"?>\n<resources>\n  <color name="ic_launcher_background">#241e47</color>\n</resources>\n');
  console.log('[patch-android-bridge] ic_launcher_background.xml ter-patch ke #241e47.');
}
